<body>
<div class="container">
  <h1>Window herb light planner</h1>
  <p class="subtitle">Match your kitchen herbs to your actual windowsill conditions.</p>

  <div class="form-grid">
    <div class="field">
      <label for="direction">Window direction</label>
      <select id="direction">
        <option value="south">South-facing</option>
        <option value="east">East-facing</option>
        <option value="west">West-facing</option>
        <option value="north">North-facing</option>
      </select>
    </div>
    <div class="field">
      <label for="hours">Direct sun (hours/day)</label>
      <input type="number" id="hours" min="0" max="12" value="4" step="0.5">
    </div>
    <div class="field">
      <label for="sillW">Sill width (inches)</label>
      <input type="number" id="sillW" min="4" max="48" value="12">
    </div>
    <div class="field">
      <label for="sillD">Sill depth (inches)</label>
      <input type="number" id="sillD" min="3" max="18" value="6">
    </div>
    <div class="field full">
      <label>Herbs you want to grow</label>
      <div class="herb-grid" id="herbGrid"></div>
    </div>
  </div>

  <button class="plan-btn" id="planBtn">Plan my windowsill ↗</button>

  <div class="results" id="results">
    <hr class="divider">

    <div class="sill-viz">
      <div class="sill-label" id="sillLabel">Your windowsill layout</div>
      <div class="sill-scene">
        <div class="window-pane"></div>
        <div class="pots-row" id="potsRow"></div>
        <div class="sill-wood"></div>
      </div>
      <div class="overflow-note" id="overflowNote"></div>
    </div>

    <div class="no-fit-msg" id="noFitMsg"></div>

    <p class="section-title">Herb care guide</p>
    <div class="herb-cards" id="herbCards"></div>

    <p class="section-title">Light summary</p>
    <div class="tip-box" id="lightTip"><p></p></div>

    <p class="section-title" id="altTitle" style="display:none">Consider this too</p>
    <div class="tip-box alt" id="altTip" style="display:none"><p></p></div>
  </div>
</div>

<script>
const HERBS = [
  { id:'basil',      name:'Basil',      icon:'🌿', minSun:6,  water:'Every 2–3 days',  potColor:'#2d7a45', rimColor:'#1f5a32', potW:46, potH:36, light:'Full sun (6h+)',      tip:'Pinch flowers immediately to extend the harvest season. Loves warmth — keep away from cold drafts near the glass in winter.' },
  { id:'mint',       name:'Mint',       icon:'🍃', minSun:3,  water:'Every 2 days',    potColor:'#3a7d44', rimColor:'#285a30', potW:44, potH:34, light:'Part sun (3h+)',      tip:'Keep in its own pot — it will take over neighbors. Very forgiving of lower light. Cut back hard to keep bushy.' },
  { id:'cilantro',   name:'Cilantro',   icon:'🌱', minSun:4,  water:'Every 2–3 days',  potColor:'#5a8e5a', rimColor:'#3d6b3d', potW:44, potH:34, light:'Part–full sun (4h+)', tip:'Bolts quickly in heat or strong afternoon sun. East-facing windows are ideal. Succession-sow every 3 weeks for continuous harvest.' },
  { id:'parsley',    name:'Parsley',    icon:'🥬', minSun:4,  water:'Every 3 days',    potColor:'#4a8040', rimColor:'#345c2c', potW:44, potH:34, light:'Part–full sun (4h+)', tip:'Slow to establish — be patient the first few weeks. Keep consistently moist but ensure good drainage. Tolerates partial light well.' },
  { id:'thyme',      name:'Thyme',      icon:'🌾', minSun:6,  water:'Every 4–5 days',  potColor:'#8c7a4a', rimColor:'#6b5c34', potW:40, potH:30, light:'Full sun (6h+)',      tip:'Drought-tolerant — let soil dry out between waterings. A Mediterranean native that handles neglect better than overwatering.' },
  { id:'rosemary',   name:'Rosemary',   icon:'🪴', minSun:6,  water:'Every 5–7 days',  potColor:'#6b8a6b', rimColor:'#4a6a4a', potW:50, potH:40, light:'Full sun (6h+)',      tip:'Needs excellent drainage above all else. Occasional misting helps in dry apartments. South-facing only — will decline in anything less.' },
  { id:'chives',     name:'Chives',     icon:'🧅', minSun:4,  water:'Every 3–4 days',  potColor:'#5a8040', rimColor:'#3d5c2c', potW:40, potH:32, light:'Part–full sun (4h+)', tip:'One of the most beginner-friendly herbs. Cut to 2 inches above soil and it regrows quickly. Good for east or west windows.' },
  { id:'oregano',    name:'Oregano',    icon:'🌿', minSun:6,  water:'Every 4–5 days',  potColor:'#8c6a3a', rimColor:'#6b4e28', potW:44, potH:34, light:'Full sun (6h+)',      tip:'Flavor intensifies when slightly dry-stressed. Allow soil to dry between waterings. Excellent companion to basil on a south sill.' },
  { id:'dill',       name:'Dill',       icon:'🌿', minSun:6,  water:'Every 2–3 days',  potColor:'#6aaa5a', rimColor:'#4a8040', potW:44, potH:42, light:'Full sun (6h+)',      tip:'Grows tall — place at the back of the sill so it does not shade shorter herbs. Avoid relocating once established; it hates being moved.' },
  { id:'lemonbalm',  name:'Lemon balm', icon:'🍋', minSun:3,  water:'Every 2–3 days',  potColor:'#9aaa3a', rimColor:'#728030', potW:44, potH:34, light:'Part sun (3h+)',      tip:'One of the best herbs for low-light kitchens. Aromatic and excellent for tea. Spreads aggressively outdoors — the pot keeps it civil.' },
];

const selected = new Set();
const herbGrid = document.getElementById('herbGrid');

HERBS.forEach(h => {
  const el = document.createElement('div');
  el.className = 'herb-check';
  el.dataset.id = h.id;
  el.innerHTML = `<span class="herb-icon">${h.icon}</span><span class="herb-name">${h.name}</span>`;
  el.addEventListener('click', () => {
    if (selected.has(h.id)) { selected.delete(h.id); el.classList.remove('selected'); }
    else { selected.add(h.id); el.classList.add('selected'); }
  });
  herbGrid.appendChild(el);
});

function sunIcon() {
  return `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="4"/><line x1="12" y1="2" x2="12" y2="5"/><line x1="12" y1="19" x2="12" y2="22"/><line x1="4.22" y1="4.22" x2="6.34" y2="6.34"/><line x1="17.66" y1="17.66" x2="19.78" y2="19.78"/><line x1="2" y1="12" x2="5" y2="12"/><line x1="19" y1="12" x2="22" y2="12"/><line x1="4.22" y1="19.78" x2="6.34" y2="17.66"/><line x1="17.66" y1="6.34" x2="19.78" y2="4.22"/></svg>`;
}
function dropIcon() {
  return `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2.69l5.66 5.66a8 8 0 1 1-11.31 0z"/></svg>`;
}

document.getElementById('planBtn').addEventListener('click', () => {
  const dir   = document.getElementById('direction').value;
  const hours = parseFloat(document.getElementById('hours').value) || 0;
  const sillW = parseInt(document.getElementById('sillW').value) || 12;
  const sillD = parseInt(document.getElementById('depth') ? document.getElementById('depth').value : document.getElementById('sillD').value) || 6;

  if (selected.size === 0) { alert('Select at least one herb to continue.'); return; }

  const chosen = HERBS.filter(h => selected.has(h.id));
  const fits   = chosen.filter(h => hours >= h.minSun);
  const noFit  = chosen.filter(h => hours < h.minSun);

  const potSpacing = 10;
  const avgPotW = 46;
  const maxPots = Math.max(1, Math.floor(sillW / ((avgPotW / 4) + 1)));

  const potsRow = document.getElementById('potsRow');
  potsRow.innerHTML = '';

  const toShow = fits.slice(0, maxPots);
  const scale = sillD >= 8 ? 1.15 : sillD >= 5 ? 1.0 : 0.82;

  if (toShow.length === 0) {
    const msg = document.createElement('div');
    msg.style.cssText = 'padding: 1rem; font-size: 13px; color: var(--text-secondary); z-index:2; position:relative;';
    msg.textContent = 'No herbs fit these light conditions — see recommendations below.';
    potsRow.appendChild(msg);
  } else {
    toShow.forEach(h => {
      const w = Math.round(h.potW * scale);
      const bodyH = Math.round(h.potH * scale);
      const rimH = Math.round(6 * scale);
      const wrap = document.createElement('div');
      wrap.className = 'pot-wrap';
      wrap.innerHTML = `
        <span class="pot-emoji" style="font-size:${Math.round(20*scale)}px">${h.icon}</span>
        <div class="pot-body" style="width:${w}px;height:${bodyH}px;background:${h.potColor};"></div>
        <div class="pot-rim"  style="width:${w+6}px;height:${rimH}px;background:${h.rimColor};"></div>
        <div class="pot-label">${h.name}</div>`;
      potsRow.appendChild(wrap);
    });
  }

  const overflowNote = document.getElementById('overflowNote');
  const extra = fits.slice(maxPots);
  if (extra.length > 0) {
    overflowNote.style.display = 'block';
    overflowNote.textContent = `Your ${sillW}" sill fits about ${maxPots} pots. ${extra.map(h=>h.name).join(', ')} won't fit — try a tiered shelf or a second window.`;
  } else {
    overflowNote.style.display = 'none';
  }

  document.getElementById('sillLabel').textContent =
    `${dir.charAt(0).toUpperCase()+dir.slice(1)}-facing · ${hours}h direct sun · ${sillW}" wide × ${sillD}" deep`;

  const noFitMsg = document.getElementById('noFitMsg');
  if (noFit.length > 0) {
    noFitMsg.style.display = 'block';
    noFitMsg.innerHTML = `<strong>Not enough light for:</strong> ${noFit.map(h=>`${h.icon} ${h.name} (needs ${h.minSun}h)`).join(', ')}. These will struggle or fail here without a grow light.`;
  } else {
    noFitMsg.style.display = 'none';
  }

  const herbCards = document.getElementById('herbCards');
  herbCards.innerHTML = '';
  const allToCard = [...fits, ...noFit];
  allToCard.forEach(h => {
    const surplus = hours - h.minSun;
    const ratingClass = surplus >= 2 ? 'great' : surplus >= 0 ? 'ok' : 'poor';
    const ratingText  = surplus >= 2 ? 'Thrives here' : surplus >= 0 ? 'Manageable' : 'Too little light';
    const card = document.createElement('div');
    card.className = 'herb-card';
    card.innerHTML = `
      <div class="herb-card-header">
        <span class="herb-card-name">${h.icon} ${h.name}</span>
        <span class="badge badge-${ratingClass}">${ratingText}</span>
      </div>
      <div class="herb-stat">${sunIcon()} ${h.light}</div>
      <div class="herb-stat">${dropIcon()} Water ${h.water.toLowerCase()}</div>
      <div class="herb-tip">${h.tip}</div>`;
    herbCards.appendChild(card);
  });

  const dirTips = {
    south: 'South-facing windows receive 6–8 hours of strong, consistent direct sun year-round. This is the gold standard for full-sun herbs like basil, rosemary, thyme, and oregano. In summer you may need to pull very sensitive herbs back slightly to prevent leaf scorch.',
    east:  'East-facing windows deliver gentle morning sun for roughly 4–6 hours before shifting to indirect light in the afternoon. Great for cilantro, parsley, chives, and mint. Basil and rosemary will survive but may be leggy — supplement with a grow light if you want strong production.',
    west:  'West-facing windows get hot, direct afternoon sun for 4–6 hours. Most herbs handle this well, but thin-leaved herbs like cilantro and mint can scorch in peak summer. A sheer curtain for the hottest weeks helps.',
    north: 'North-facing windows receive little to no direct sun. Only low-light tolerant herbs like mint and lemon balm can survive here, and even they will grow slowly. A clip-on LED grow light used 12–14 hours per day is strongly recommended and will open up nearly all herbs on this list.',
  };

  document.getElementById('lightTip').querySelector('p').textContent = dirTips[dir];

  const altTitle = document.getElementById('altTitle');
  const altTip   = document.getElementById('altTip');
  if (dir === 'north' || hours < 3) {
    altTitle.style.display = 'block';
    altTip.style.display   = 'block';
    altTip.querySelector('p').textContent = 'With under 3 hours of direct sun, mint and lemon balm are your safest bets without assistance. A budget LED grow light ($20–35 on Amazon) placed 6–12 inches above pots and run 12–14 hours per day effectively substitutes for 5–6 hours of direct sun and makes nearly any culinary herb viable in a north window.';
  } else {
    altTitle.style.display = 'none';
    altTip.style.display   = 'none';
  }

  const resultsEl = document.getElementById('results');
  resultsEl.style.display = 'block';
  resultsEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
});
</script>
</body>
